draw:
var F = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = F;
var a = p.angle * Math.PI / 180;
var m = p.m, M = p.M, g = 9.8;
var A = m * g * Math.sin(a) * Math.cos(a) / (M + m * Math.sin(a) * Math.sin(a));
var sdd = (M + m) * g * Math.sin(a) / (M + m * Math.sin(a) * Math.sin(a));

var floorY = H * 0.86;
var x0 = W * 0.16;
var base = W * 0.56;
var hgt = base * Math.tan(a);
if (hgt > H * 0.56) { base = (H * 0.56) / Math.tan(a); hgt = H * 0.56; }
var apexX = x0, apexY = floorY - hgt;
var rightX = x0 + base;

// floor
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(0, floorY); ctx.lineTo(W, floorY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("frictionless floor", W * 0.02, floorY + 16);

// wedge
ctx.fillStyle = C.paper;
ctx.strokeStyle = C.ink;
ctx.beginPath();
ctx.moveTo(apexX, apexY); ctx.lineTo(rightX, floorY); ctx.lineTo(apexX, floorY);
ctx.closePath(); ctx.fill(); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("M", apexX + 16, floorY - 14);

// angle mark at the bottom right corner
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(rightX, floorY, 26, Math.PI, Math.PI + a); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("alpha = " + p.angle.toFixed(0) + " deg", rightX - 78, floorY - 8);

// block a third of the way down the face
var f = 0.38;
var bx = apexX + (rightX - apexX) * f;
var by = apexY + (floorY - apexY) * f;
var bs = 18;
var nx = -Math.sin(a), ny = -Math.cos(a);
ctx.save();
ctx.translate(bx + nx * bs * 0.7, by + ny * bs * 0.7);
ctx.rotate(a);
ctx.fillStyle = C.paper;
ctx.fillRect(-bs / 2, -bs / 2, bs, bs);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.8;
ctx.strokeRect(-bs / 2, -bs / 2, bs, bs);
ctx.restore();
var cxb = bx + nx * bs * 0.7, cyb = by + ny * bs * 0.7;
ctx.fillStyle = C.ink;
ctx.fillText("m", cxb - 20, cyb - 10);

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 1.6;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 7 * Math.cos(ang - 0.4), y2 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 7 * Math.cos(ang + 0.4), y2 - 7 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
}

// normal force on block (does no work in the ground frame only if wedge is fixed)
arrow(cxb, cyb, cxb + nx * 44, cyb + ny * 44, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("N (never appears in L)", cxb + nx * 44 - 30, cyb + ny * 44 - 8);

// gravity on block
arrow(cxb, cyb, cxb, cyb + 40, C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("mg", cxb + 6, cyb + 38);

// s along the face
var sx = apexX + (rightX - apexX) * 0.70, sy = apexY + (floorY - apexY) * 0.70;
arrow(apexX, apexY, sx, sy, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("s: block along the face", apexX + 26, apexY + 34);

// X of the wedge
arrow(rightX - 40, floorY + 26, rightX + 20, floorY + 26, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("X: wedge along the floor", rightX - 150, floorY + 42);

out.note = "wedge acceleration " + A.toFixed(2) + " m/s^2, block along the face " +
  sdd.toFixed(2) + " m/s^2";

var F = "12px ui-sans-serif, system-ui, sans-serif";
var M = p.M, m = p.m, L = p.L, g = 9.8;
var w = Math.sqrt(g * (M + m) / (M * L));
var th0 = 0.30;
var th = th0 * Math.cos(w * t);

var railY = H * 0.26;
var mid = W * 0.5;
var scale = (H * 0.56) / L;
var xc = -(m * L / (M + m)) * Math.sin(th);
var cx = mid + xc * scale;

ctx.lineWidth = 1;
ctx.font = F;

// rail
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(W * 0.06, railY); ctx.lineTo(W * 0.94, railY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("frictionless rail", W * 0.06, railY - 8);

// centre line
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(mid, railY - 14); ctx.lineTo(mid, H * 0.92); ctx.stroke();
ctx.setLineDash([]);

// cart
var cw = Math.max(36, W * 0.13), ch = 20;
ctx.fillStyle = C.paper;
ctx.fillRect(cx - cw / 2, railY - ch, cw, ch);
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.strokeRect(cx - cw / 2, railY - ch, cw, ch);
ctx.fillStyle = C.ink;
ctx.fillText("M", cx - 4, railY - ch / 2 + 4);

// rod and bob
var bx = cx + L * scale * Math.sin(th);
var by = railY + L * scale * Math.cos(th);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, railY); ctx.lineTo(bx, by); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 8, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("m", bx + 12, by + 4);

// vertical from pivot, and theta label
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(cx, railY); ctx.lineTo(cx, railY + L * scale); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.arc(cx, railY, 30, Math.PI / 2, Math.PI / 2 - th, th > 0);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("theta", cx + (th > 0 ? 10 : -40), railY + 46);

// cart displacement arrow
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(mid, railY - 34); ctx.lineTo(cx, railY - 34); ctx.stroke();
ctx.beginPath();
var dir = cx >= mid ? 1 : -1;
ctx.moveTo(cx, railY - 34); ctx.lineTo(cx - dir * 6, railY - 38); ctx.lineTo(cx - dir * 6, railY - 30);
ctx.closePath(); ctx.fillStyle = C.accent; ctx.fill();
ctx.fillStyle = C.accent;
ctx.fillText("cart recoil X", mid - 30, railY - 42);

out.note = "omega = " + w.toFixed(2) + " rad/s   (fixed pivot would give " +
  Math.sqrt(g / L).toFixed(2) + ")   cart amplitude " +
  (m * L / (M + m) * Math.sin(th0)).toFixed(3) + " m";

var F = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = F;
var R = p.R, w = p.spin, g = 9.8;
var beta = w * w * R / g;
var supercrit = beta > 1;
var th0 = supercrit ? Math.acos(1 / beta) : 0;
var wosc = supercrit ? w * Math.sqrt(1 - 1 / (beta * beta)) : Math.sqrt(g / R - w * w);
var amp = 0.20;
var th = th0 + amp * Math.cos(wosc * t);

// ---- left panel: the hoop ----
var cxh = W * 0.22, cyh = H * 0.48;
var rad = Math.min(W * 0.17, H * 0.34);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cxh, cyh, rad, 0, Math.PI * 2); ctx.stroke();
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cxh, cyh - rad - 16); ctx.lineTo(cxh, cyh + rad + 16); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("spin axis", cxh + 6, cyh - rad - 6);

// bead
var bxp = cxh + rad * Math.sin(th), byp = cyh + rad * Math.cos(th);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cxh, cyh); ctx.lineTo(bxp, byp); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bxp, byp, 7, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(cxh, cyh, 22, Math.PI / 2, Math.PI / 2 - th, th > 0);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("theta from the bottom", cxh - 40, cyh + rad + 30);

// ---- right panel: effective potential ----
var px0 = W * 0.46, px1 = W * 0.96;
var py0 = H * 0.16, py1 = H * 0.80;
var lo = -2.6, hi = 2.6;
function u(x) { return (1 - Math.cos(x)) - 0.5 * beta * Math.sin(x) * Math.sin(x); }
var umin = 1e9, umax = -1e9, i, xx, vv;
for (i = 0; i <= 200; i++) {
  xx = lo + (hi - lo) * i / 200; vv = u(xx);
  if (vv < umin) umin = vv;
  if (vv > umax) umax = vv;
}
if (umax - umin < 1e-6) { umax = umin + 1; }
function PX(x) { return px0 + (x - lo) / (hi - lo) * (px1 - px0); }
function PY(v) { return py1 - (v - umin) / (umax - umin) * (py1 - py0); }

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(PX(0), py0 - 6); ctx.lineTo(PX(0), py1 + 6); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px0, PY(u(0))); ctx.lineTo(px1, PY(u(0))); ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 200; i++) {
  xx = lo + (hi - lo) * i / 200;
  if (i === 0) ctx.moveTo(PX(xx), PY(u(xx))); else ctx.lineTo(PX(xx), PY(u(xx)));
}
ctx.stroke();

// bead on the curve
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(PX(th), PY(u(th)), 6, 0, Math.PI * 2); ctx.fill();

// equilibrium markers
ctx.strokeStyle = C.accent;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(PX(th0), PY(u(th0))); ctx.lineTo(PX(th0), py1 + 4); ctx.stroke();
if (supercrit) {
  ctx.beginPath(); ctx.moveTo(PX(-th0), PY(u(-th0))); ctx.lineTo(PX(-th0), py1 + 4); ctx.stroke();
}
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("effective potential U(theta)", px0, py0 - 4);
ctx.fillStyle = C.faint;
ctx.fillText("theta", px1 - 26, py1 + 18);
ctx.fillStyle = C.accent;
ctx.fillText(supercrit ? "tilted minimum" : "bottom is stable", PX(th0) - 30, py1 + 18);

out.note = supercrit
  ? "spinning above critical: equilibrium at " + (th0 * 180 / Math.PI).toFixed(1) +
    " deg, small oscillations at " + wosc.toFixed(2) + " rad/s"
  : "below critical (" + Math.sqrt(g / R).toFixed(2) +
    " rad/s): bottom still stable, small oscillations at " + wosc.toFixed(2) + " rad/s";
